{
  "title": "A Slow Day in Đà Lạt",
  "summary": "A gentle day with a morning pagoda, a long lunch, and an evening market stroll, leaving plenty of room to breathe and watch the pines.",
  "stops": [
    {
      "poi_id": "p8",
      "kind": "activity",
      "must_do_id": "p8",
      "note": "Morning light on the mosaic dragons is worth the ride, and the crew can linger without a single clock watching.",
      "must_do_id": "p8"
    },
    {
      "poi_id": "p157",
      "kind": "meal",
      "must_do_id": "p157",
      "note": "Lunch stays right here because the nem nướng deserves a slow, happy chew, not a rushed bite.",
      "must_do_id": "p157"
    },
    {
      "poi_id": "p14",
      "kind": "activity",
      "must_do_id": null,
      "note": "A short, easy wander by the square for local life and photo stops, then we let the afternoon melt into coffee time.",
      "must_do_id": null
    },
    {
      "poi_id": "p330",
      "kind": "meal",
      "must_do_id": null,
      "note": "Dinner with a coffee in hand and a seat that says stay a while, because night owls and slow days are old friends.",
      "must_do_id": null
    },
    {
      "poi_id": "p144",
      "kind": "activity",
      "must_do_id": null,
      "note": "After dark, the complex glows and hums, just enough local nightlife to close the day without rushing anywhere.",
      "must_do_id": null
    }
  ]
}
